<section class="vc-page-actions"><div><span class="vc-status info" id="vsp-status">Loading your tickets…</span></div><button type="button" class="vc-btn primary" id="vsp-new">Open support ticket</button></section>
<section class="vc-card"><div class="vc-card-head"><h2>Your support tickets</h2></div><div class="vc-table-wrap"><table class="vc-table"><thead><tr><th>Ticket</th><th>Subject</th><th>Category</th><th>Status</th><th>Updated</th><th>Action</th></tr></thead><tbody id="vsp-rows"><tr><td colspan="6">Loading…</td></tr></tbody></table></div></section>
<section class="vc-card mt-3" id="vsp-detail" hidden><div class="vc-card-head"><h2 id="vsp-detail-title">Ticket</h2><button type="button" class="vc-btn small" id="vsp-hide">Close detail</button></div><div class="vc-card-body"><div class="vc-list" id="vsp-messages"></div><form id="vsp-reply" class="mt-3"><div class="vc-field"><label>Your reply</label><textarea class="vc-textarea" name="message" required minlength="10" maxlength="5000" rows="4"></textarea></div><button class="vc-btn primary mt-3" type="submit">Send reply</button></form></div></section>
<dialog class="vc-dialog" id="vsp-dialog"><div class="vc-dialog-head"><h2>Open support ticket</h2><button type="button" class="vc-btn small" id="vsp-close">Close</button></div><form class="vc-dialog-body" id="vsp-form"><div class="vc-field"><label>Category</label><select class="vc-select" name="category" required><option value="order">Order</option><option value="payment">Payment</option><option value="product">Product</option><option value="account">Account</option><option value="return">Return</option><option value="other">Other</option></select></div><div class="vc-field"><label>Subject</label><input class="vc-input" name="subject" required minlength="5" maxlength="180"></div><div class="vc-field"><label>Describe the issue</label><textarea class="vc-textarea" name="message" required minlength="10" maxlength="5000" rows="6"></textarea></div><div class="vc-form-actions"><button class="vc-btn primary" type="submit">Submit ticket</button></div></form></dialog>
